const SEGMENT_CHARS = 'abcdefghijkmnpqrstuvwxyz23456789';

function randomSegment(length) {
  let result = '';
  for (let i = 0; i < length; i += 1) {
    const index = Math.floor(Math.random() * SEGMENT_CHARS.length);
    result += SEGMENT_CHARS[index];
  }
  return result;
}

/**
 * Generates a placeholder Google Meet-style Meeting ID (e.g., "kxp-m4rt-vbn").
 * Production Meeting IDs will be generated by the backend.
 */
export function generatePlaceholderMeetingId() {
  return `${randomSegment(3)}-${randomSegment(4)}-${randomSegment(3)}`;
}

export function buildMeetingLink(meetingId) {
  const origin =
    typeof window !== 'undefined' && window.location?.origin
      ? window.location.origin
      : 'https://meetspace.app';
  return `${origin}/room/${meetingId}`;
}

export async function copyTextToClipboard(text) {
  if (typeof navigator !== 'undefined' && navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(text);
    return true;
  }
  return false;
}

